def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to separate build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate pre-release
        if '-' in version_without_build:
            main_part, prerelease_part = version_without_build.split('-', 1)
        else:
            main_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = main_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both have no pre-release, they're equal
        if pre1 is None and pre2 is None:
            return 0
        # A version with pre-release sorts before one without
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all-digit
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                # id1 is numeric, id2 is not: numeric sorts first
                return -1
            elif is_digit2:
                # id2 is numeric, id1 is not
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(version_with_index):
        version, index = version_with_index
        major, minor, patch, prerelease = parse_version(version)

        # For pre-release: convert to tuple for sorting
        # We need to create a sort key that respects the comparison rules
        if prerelease is None:
            prerelease_key = (1,)  # Non-prerelease versions sort after prerelease
        else:
            # Create a key for prerelease identifiers
            prerelease_key = (0,) + tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            )

        return (major, minor, patch, prerelease_key, index)

    # Add original indices to maintain stable sort
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort using the key function
    sorted_versions = sorted(indexed_versions, key=sort_key)

    # Return just the version strings
    return [v for v, _ in sorted_versions]

